def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = set()
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        q.append((nx, ny))

            minr = min(x for x, y in cells)
            maxr = max(x for x, y in cells)
            minc = min(y for x, y in cells)
            maxc = max(y for x, y in cells)

            # A shape with an enclosed empty cell is moved toward the top.
            exterior = set()
            q = deque()
            for x in range(minr, maxr + 1):
                for y in (minc, maxc):
                    if (x, y) not in cells and (x, y) not in exterior:
                        exterior.add((x, y))
                        q.append((x, y))
            for y in range(minc, maxc + 1):
                for x in (minr, maxr):
                    if (x, y) not in cells and (x, y) not in exterior:
                        exterior.add((x, y))
                        q.append((x, y))
            while q:
                x, y = q.popleft()
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if minr <= nx <= maxr and minc <= ny <= maxc and (nx, ny) not in cells and (nx, ny) not in exterior:
                        exterior.add((nx, ny))
                        q.append((nx, ny))
            has_hole = any(
                (x, y) not in cells and (x, y) not in exterior
                for x in range(minr, maxr + 1)
                for y in range(minc, maxc + 1)
            )
            objects.append({
                "cells": cells,
                "top": minr,
                "bottom": maxr,
                "left": minc,
                "up": has_hole,
            })

    out = [[0] * w for _ in range(h)]
    occupied = set()

    def place(obj, shift):
        return {(r + shift, c) for r, c in obj["cells"]}

    # Pack enclosed shapes upward, preserving their horizontal positions.
    upward = sorted((o for o in objects if o["up"]),
                    key=lambda o: (o["top"], o["left"]))
    for obj in upward:
        for shift in range(-obj["top"], h - obj["bottom"]):
            cells = place(obj, shift)
            if all(0 <= r < h and (r, c) not in occupied for r, c in cells):
                occupied.update(cells)
                for r, c in cells:
                    out[r][c] = grid[next(orow for orow, ocol in obj["cells"]
                                          if ocol == c and orow + shift == r)][c]
                break

    # Pack the remaining shapes downward.
    downward = sorted((o for o in objects if not o["up"]),
                      key=lambda o: (-o["bottom"], o["left"]))
    for obj in downward:
        start = h - 1 - obj["bottom"]
        for shift in range(start, -obj["top"] - 1, -1):
            cells = place(obj, shift)
            if all(0 <= r < h and (r, c) not in occupied for r, c in cells):
                occupied.update(cells)
                for r, c in cells:
                    original_r = next(orow for orow, ocol in obj["cells"]
                                      if ocol == c and orow + shift == r)
                    out[r][c] = grid[original_r][c]
                break

    return out
